"""Legal information pages, with operator details supplied separately."""
from html import escape
from datetime import date
from site_config import site_url

LAW = 'https://www.consultant.ru/document/cons_doc_LAW_61801/'
CONSENT_LAW = LAW + '6c94959bc017ac80140621762d2ac59f6006b08c/'
RIGHTS_LAW = LAW + '34585db685164ddd73440bf08348903bff6715aa/'
HOSTING_PRIVACY = 'https://timeweb.com/tw-static/docs/policy/personal_data.pdf'
SITE_URL = site_url()


def operator_block(settings):
    operator = settings['operator']
    ready = all(operator.get(key, '').strip() for key in ('name', 'address', 'email'))
    if not ready:
        return '<div class="legal-note"><strong>Сведения об операторе</strong><p>Полное наименование, реквизиты и контакт для обращений по персональным данным будут опубликованы до начала приёма заявок через сайт. Сейчас отправка заявок недоступна.</p></div>'
    rows = [('Оператор', operator['name']), ('Адрес', operator['address'])]
    if operator.get('inn'):
        rows.append(('ИНН', operator['inn']))
    content = ''.join(f'<div><dt>{escape(label)}</dt><dd>{escape(value)}</dd></div>' for label, value in rows)
    email = escape(operator['email'], quote=True)
    return f'<dl class="operator-details">{content}<div><dt>Обращения и отзыв согласия</dt><dd><a href="mailto:{email}">{email}</a></dd></div></dl>'


