def render_document(document, settings):
    updated = date.fromisoformat(settings['updated'])
    months = ('января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря')
    date_label = f'{updated.day} {months[updated.month - 1]} {updated.year}'
    title = escape(document['title'])
    toc = ''.join(f'<a href="#{ident}"><span>{number:02}</span>{escape(heading)}</a>' for number, (ident, heading, _) in enumerate(document['sections'], 1))
    sections = ''.join(f'<section class="legal-section" id="{ident}"><div class="legal-section-heading"><span aria-hidden="true">{number:02}</span><h2>{escape(heading)}</h2></div>{content}</section>' for number, (ident, heading, content) in enumerate(document['sections'], 1))
    href, label = document['related']
    return f'''
    <div class="shell breadcrumb"><a href="index.html">Главная</a><span>/</span><span>Правовая информация</span></div>
    <header class="shell legal-hero"><p class="legal-eyebrow">Правовая информация</p><h1>{title}</h1><p class="legal-lead">{escape(document['lead'])}</p><div class="legal-meta"><time datetime="{settings['updated']}">Редакция от {date_label}</time><span>External Language Education</span></div></header>
    <div class="shell legal-layout"><aside class="legal-sidebar"><details class="legal-toc" open><summary>Содержание документа</summary><nav aria-label="Содержание документа">{toc}</nav></details><a class="legal-related" href="{href}">{escape(label)}<span aria-hidden="true">↗</span></a></aside><article class="legal-document" aria-label="{title}">{sections}<div class="legal-document-end"><a href="#main">К началу документа <span aria-hidden="true">↑</span></a></div></article></div>'''
